def get_axioms() -> list:
    return []


def get_vars() -> dict:
    self = TensorVar('self')
    ord = ScalarVar('ord')
    dim = OptVar('dim', IntArrayVar('dim' + '.val'))
    dtype = OptVar('dtype', Int('dtype' + '.val'))
    out = TensorVar('out')
    return {'self': self, 'ord': ord, 'dim': dim, 'dtype': dtype, 'out': out}


def build_solver() -> Solver:
    s = Solver()
    s.add(*get_axioms())
    return s
